import {positionMath,validateDraft} from './math.js';
import {chart,spark,startArt} from './terminal-visuals.js';

export function createTerminal(ctx){
 const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=n=>Number.isFinite(n)?'$'+n.toLocaleString('en-US',{maximumFractionDigits:n<.01?8:2,minimumFractionDigits:n<.01?4:2}):'—';
 const num=n=>Number.isFinite(n)?n.toLocaleString('en-US',{maximumFractionDigits:n<10?4:2}):'—';
 const compact=n=>Number.isFinite(n)?'$'+new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:2}).format(n):'—';
 const pct=n=>Number.isFinite(n)?(n>=0?'+':'')+n.toFixed(2)+'%':'—';
 const safeURL=(u,fallback='#')=>/^https:\/\//.test(u||'')?esc(u):fallback;
 const markets=['ETH','BTC','SOL','XRP','BNB','DOGE'];
 let symbol='SOL',side='long',leverage=3,margin=0,interval='1h',line=false,cursor=-1,slippage=1,paper=false,tab='Market info',poolType='all',poolSort='volume',launchFilter='All',launchSort='newest',launchData=null,launchLoading=false,swapReverse=false,swapAmount=0,swapSlip=.5,draftId=null,image='',quote='SOL',tier='standard';
 let positions=ctx.read('positions').filter(p=>markets.includes(p.symbol)&&p.entry>0&&p.margin>0),history=ctx.read('paper-history'),watchlist=ctx.read('watchlist');
 const cache=new Map();let chartLoading='',renderedPath='';
 const m=()=>ctx.market(symbol),amountLabel=()=>ctx.wallet().address?'Connected wallet':'Connect wallet';
 const coin=s=>`<span class="t-coin ${s.toLowerCase()}">${s==='SOL'?'<svg viewBox="0 0 24 24"><defs><linearGradient id="sol-grad" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#9945ff"/><stop offset="1" stop-color="#14f195"/></linearGradient></defs><path d="M5 4h16l-4 4H1zm-4 6h16l4 4H5zm4 6h16l-4 4H1z" fill="url(#sol-grad)"/></svg>':({BTC:'₿',ETH:'♦',XRP:'×',BNB:'◆',DOGE:'Ð',USDC:'$'}[s]||esc(s[0]))}</span>`;
 const funding=()=>'<div class="t-funding"><button type="button" class="active" data-public>Public</button><button type="button" data-shielded title="Shielded transfers are not deployed on this Solana preview">Shielded</button></div>';
 function hero(kicker,title,copy,art='curve',buttons=''){return `<div class="t-hero"><div><p class="t-kicker mono">${kicker}</p><h1>${title}</h1><p>${copy}</p>${buttons?`<div class="t-hero-actions">${buttons}</div>`:''}</div><canvas class="app-art" data-art="${art}" aria-hidden="true"></canvas></div>`;}
 function header(){let el=$('.header-funding');if(!el){el=document.createElement('div');el.className='header-funding';$('.header-right').prepend(el);}el.innerHTML=funding();$('.header-right').querySelectorAll(':scope>a.round').forEach(a=>a.classList.add('app-hide-round'));}
 function bindFunding(){$$('[data-public]').forEach(b=>b.onclick=()=>ctx.toast('Public Solana workspace selected'));$$('[data-shielded]').forEach(b=>b.onclick=()=>ctx.navigate('/app/vault'));}
 function walletButton(text='Connect wallet'){return `<button type="button" class="button white connect t-full">${ctx.wallet().address?esc(amountLabel()):text}</button>`;}
 function series(){const current=cache.get(symbol+interval);return current?.candles||m()?.candles||[];}
 function drawChart(){const c=$('#app-chart');if(!c)return;const values=series();chart(c,values,{line,cursor,symbol,interval:cache.has(symbol+interval)?interval:'1D fallback',mark:m()?.price});const note=$('#t-chart-source');if(note)note.textContent=cache.has(symbol+interval)?`${symbol} / USD · ${interval} · Binance exchange reference · ${new Date(cache.get(symbol+interval).asOf).toLocaleTimeString('en-US')}`:ctx.sourceLabel();}
 async function loadChart(){const key=symbol+interval;if(cache.has(key)){drawChart();return;}if(chartLoading===key)return;chartLoading=key;try{const response=await fetch(`/api/candles?symbol=${symbol}&interval=${interval}`,{signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error();const data=await response.json();if(Array.isArray(data.candles)&&data.candles.length)cache.set(key,data);}catch{}finally{if(chartLoading===key)chartLoading='';if($('#app-chart'))drawChart();}}
 function marketRow(s){const a=ctx.market(s);return `<button class="t-market ${symbol===s?'active':''}" data-symbol="${s}">${coin(s)}<span><strong>${s}-USD</strong><small data-price-symbol="${s}">${num(a?.price)}</small></span><span class="t-market-trend">${spark(a?.candles)}<small data-change-symbol="${s}" class="${a?.change<0?'bad':'good'}">${pct(a?.change)}</small></span></button>`;}
 function sidebar(){const wallet=ctx.wallet();return `<aside class="t-sidebar"><section class="panel t-watch"><div class="t-card-head"><h2>Markets</h2><span class="pill">${markets.length}</span></div><input class="search-input" id="market-search" placeholder="⌕  Search markets" aria-label="Search markets"><div class="t-market-head"><span>Market</span><span>24h</span></div><div class="t-market-list">${markets.map(marketRow).join('')}</div></section><section class="panel t-bal"><h2>Balances</h2><div class="balance-card"><strong>▱ &nbsp; Public wallet</strong><div><span>SOL</span><b id="t-wallet-balance">${wallet.address?(wallet.balance===null?'Unavailable':num(wallet.balance)):'Not connected'}</b></div></div><a class="balance-card t-vault-link" href="/app/vault"><strong>♧ &nbsp; Shielded vault</strong><div><span>Solana module</span><b>Not deployed</b></div></a></section><section class="panel t-bal"><div class="t-card-head"><h2>Liquidity</h2><span class="pill">Solana</span></div><p class="caption">Explore actual pool liquidity and choose a venue before supplying funds.</p><div class="definition"><div><span>Visible pool sample</span><b>${compact((ctx.data()?.pools||[]).reduce((n,p)=>n+(p.liquidity||0),0))}</b></div></div><a class="button t-full" href="/app/pools">Provide liquidity</a></section></aside>`;}
 function perps(){return `<div class="t-terminal">${sidebar()}<div class="t-terminal-main"><div class="t-center"><section class="panel t-chart-panel"><div class="t-chart-head"><div class="t-chart-title">${coin(symbol)}<button id="change-market" title="Change market">${symbol} / USD ⌄</button><span class="pill">Up to 5×</span><strong id="t-current">${num(m()?.price)}</strong><small id="t-change" class="${m()?.change<0?'bad':'good'}">${pct(m()?.change)}</small></div><div class="t-stats"><div>24h high<strong id="t-high">${num(m()?.high)}</strong></div><div>24h low<strong id="t-low">${num(m()?.low)}</strong></div><div>Reference<strong id="t-reference">${num(m()?.price)}</strong></div><div>Funding 1h<strong>—</strong></div><div>Open interest<strong>— <small>USDC</small></strong></div><div>Volume 24h<strong id="t-volume">${compact(m()?.volume)}</strong></div></div></div><div class="t-chart-toolbar"><div class="segments">${['1m','5m','15m','1h','6h','1d'].map(v=>`<button data-interval="${v}" class="${interval===v?'active':''}">${v==='1d'?'1D':v}</button>`).join('')}</div><div class="segments t-chart-tools"><button id="chart-type" title="Toggle line and candles" aria-label="Toggle line and candles">⌁</button><button id="chart-full" title="Full screen" aria-label="Full screen chart">⛶</button><button id="chart-save" title="Save chart" aria-label="Save chart image">▣</button></div></div><div id="t-chart-wrap"><canvas id="app-chart" class="t-candles" aria-label="${symbol} price chart"></canvas></div><div id="t-chart-source" class="chart-source">${esc(ctx.sourceLabel())}</div></section><section class="panel t-account"><div class="table-tabs">${['Market info','Positions','Pending','TP / SL','History','Market trades'].map(t=>`<button data-table="${t}" class="${tab===t?'active':''}">${t}</button>`).join('')}</div><div id="t-account-content"></div></section><section class="panel t-liquidity"><h2>Provide liquidity</h2><p class="caption">Solana pool discovery. Deposits and their terms are handled by the selected venue.</p><div class="t-facts"><div><small>VISIBLE LIQUIDITY</small><strong>${compact((ctx.data()?.pools||[]).reduce((n,p)=>n+(p.liquidity||0),0))}</strong></div><div><small>NETWORK</small><strong>Solana</strong></div><div><small>CUSTODY</small><strong>Your wallet</strong></div></div><a class="button white" href="/app/pools">Explore pools →</a></section></div><aside class="panel t-order"><div class="t-card-head"><h2>Trade ${symbol}-USD</h2>${funding()}</div><div class="order-badges"><span>Isolated</span><span>Market</span><span>Up to 5×</span></div><div class="long-short"><button data-side="long" class="${side==='long'?'active':''}">Long</button><button data-side="short" class="short ${side==='short'?'active':''}">Short</button></div><div class="amount-label"><span>Available</span><span>${paper?'Paper mode':'—'}</span></div><div class="amount-box"><label for="margin-input">Margin</label><div class="amount-value"><input id="margin-input" type="number" min="0" max="1000000" step="any" value="${margin||''}" placeholder="0"><span>USDC</span></div></div><div class="t-percent">${[25,50,75,100].map(v=>`<button data-share="${v}" ${paper?'':'disabled'}>${v}%</button>`).join('')}</div><div class="leverage-label"><span>Leverage</span><b id="leverage-text">${leverage}×</b></div><div class="leverage-buttons">${[1,2,3,5].map(v=>`<button data-leverage="${v}" class="${v===leverage?'active':''}">${v}×</button>`).join('')}</div><div class="t-slippage"><span>Max slippage</span><div class="segments">${[.3,1,2].map(v=>`<button data-slippage="${v}" class="${slippage===v?'active':''}">${v}%</button>`).join('')}</div></div><div class="t-order-action"><p>${paper?'Paper position only. No funds move.':'Connect a Solana wallet or explore the paper model. Live execution continues on Jupiter.'}</p>${paper?'<button class="button white t-full" id="save-position">Save paper position</button>':walletButton()}<button id="paper-mode" class="t-quiet">${paper?'Leave paper mode':'Try paper mode'}</button></div><dl class="definition"><div><dt>Liquidation price</dt><dd id="calc-liq">—</dd></div><div><dt>Order value</dt><dd id="calc-size">—</dd></div><div><dt>Margin</dt><dd id="calc-margin">—</dd></div><div><dt>Move to liquidation</dt><dd id="calc-distance">—</dd></div><div><dt>Fees / funding</dt><dd>Excluded</dd></div><div><dt>Execution venue</dt><dd><a href="https://jup.ag/perps" target="_blank" rel="noopener">Jupiter ↗</a></dd></div></dl><p class="caption t-order-note">This preview models positions; it does not submit a real order. Leverage magnifies losses.</p></aside></div></div>`;}
 function updateMath(){const p=positionMath({entry:m()?.price,mark:m()?.price,margin,leverage,side});for(const [id,value] of Object.entries({'calc-liq':p?money(p.liquidation):'—','calc-size':p?money(p.size):'—','calc-margin':p?money(margin):'—','calc-distance':p?p.distance.toFixed(2)+'%':'—'})){const e=$('#'+id);if(e)e.textContent=value;}}
 function account(){const el=$('#t-account-content');if(!el)return;if(tab==='Market info'){const longs=positions.filter(p=>p.side==='long'&&p.symbol===symbol).reduce((n,p)=>n+p.margin*p.leverage,0),shorts=positions.filter(p=>p.side==='short'&&p.symbol===symbol).reduce((n,p)=>n+p.margin*p.leverage,0),total=longs+shorts;el.innerHTML=`<div class="t-interest"><div class="amount-label"><span>OPEN INTEREST, LONG AGAINST SHORT</span><span>Local paper positions</span></div><div class="t-split"><i style="width:${total?longs/total*100:50}%"></i><i></i></div><div class="t-between"><span>Long · ${money(longs)}</span><span>Short · ${money(shorts)}</span></div></div><div class="t-market-details"><h2>Market details</h2><div class="t-facts"><div><small>MAX LEVERAGE</small><strong>5×</strong></div><div><small>COLLATERAL MODEL</small><strong>USDC</strong></div><div><small>MAINTENANCE MARGIN</small><strong>2.00%</strong></div><div><small>REFERENCE SOURCE</small><strong>Binance</strong></div><div><small>FUNDING</small><strong>Not modeled</strong></div><div><small>EXECUTION</small><strong>Paper / external</strong></div></div><p class="caption">Public exchange references. The local model excludes venue fees, slippage and funding; it is not a live Solana perpetual contract.</p></div>`;}else if(tab==='Positions'||tab==='History'){const list=tab==='History'?history:positions;el.innerHTML=list.length?`<div class="t-scroll"><table class="t-table"><thead><tr><th>Market</th><th>Size</th><th>Entry</th><th>PNL</th><th></th></tr></thead><tbody>${list.slice().reverse().map(p=>{const calc=positionMath({...p,mark:ctx.market(p.symbol)?.price||p.entry});return `<tr><td>${esc(p.symbol)} <small class="${p.side==='long'?'good':'bad'}">${esc(p.side)} ${p.leverage}×</small></td><td>${money(p.margin*p.leverage)}</td><td>${money(p.entry)}</td><td class="${calc?.pnl>=0?'good':'bad'}">${calc?money(calc.pnl):'—'}</td><td>${tab==='Positions'?`<button data-close-position="${esc(p.id)}" class="button">Close</button>`:'Paper'}</td></tr>`;}).join('')}</tbody></table></div>`:'<p class="empty">No paper positions in this view.</p>';$$('[data-close-position]').forEach(b=>b.onclick=()=>{const p=positions.find(p=>p.id===b.dataset.closePosition);if(p){history.push({...p,closedAt:new Date().toISOString()});history=history.slice(-50);ctx.write('paper-history',history);}positions=positions.filter(p=>p.id!==b.dataset.closePosition);ctx.write('positions',positions);account();});}else if(tab==='Market trades'){el.innerHTML=`<div class="t-scroll"><table class="t-table"><thead><tr><th>Side</th><th>Price</th><th>Size</th><th>Time</th></tr></thead><tbody>${(ctx.data()?.tape||[]).map(t=>`<tr><td class="${t.side==='Buy'?'good':'bad'}">${t.side}</td><td>${num(t.price)}</td><td>${num(t.quantity)} SOL</td><td>${new Date(t.time).toLocaleTimeString('en-GB')}</td></tr>`).join('')}</tbody></table></div><p class="caption t-pad">SOL/USDT exchange tape · public reference, not trades submitted here.</p>`;}else el.innerHTML=`<p class="empty">No ${tab==='Pending'?'pending execution requests':'take-profit or stop-loss orders'}. This Solana preview does not submit live orders.</p>`;}
 function bindPerps(){$$('[data-symbol]').forEach(b=>b.onclick=()=>{symbol=b.dataset.symbol;render('/app/perps');});$('#market-search').oninput=e=>$$('[data-symbol]').forEach(b=>b.classList.toggle('hidden',!b.dataset.symbol.includes(e.target.value.toUpperCase())));$('#change-market').onclick=()=>$('#market-search').focus();$$('[data-side]').forEach(b=>b.onclick=()=>{side=b.dataset.side;$$('[data-side]').forEach(e=>e.classList.toggle('active',e===b));updateMath();});$$('[data-leverage]').forEach(b=>b.onclick=()=>{leverage=+b.dataset.leverage;$('#leverage-text').textContent=leverage+'×';$$('[data-leverage]').forEach(e=>e.classList.toggle('active',e===b));updateMath();});$$('[data-slippage]').forEach(b=>b.onclick=()=>{slippage=+b.dataset.slippage;$$('[data-slippage]').forEach(e=>e.classList.toggle('active',e===b));});$$('[data-share]').forEach(b=>b.onclick=()=>{margin=1000*Number(b.dataset.share)/100;$('#margin-input').value=margin;updateMath();});$('#margin-input').oninput=e=>{margin=+e.target.value;updateMath();};$('#paper-mode').onclick=()=>{paper=!paper;render('/app/perps');};$('#save-position')&&($('#save-position').onclick=()=>{if(!positionMath({entry:m()?.price,mark:m()?.price,margin,leverage,side})){ctx.toast('Enter a positive margin and wait for a market price.');return;}positions.push({id:crypto.randomUUID(),symbol,entry:m().price,margin,leverage,side,createdAt:new Date().toISOString()});positions=positions.slice(-30);ctx.write('positions',positions);tab='Positions';$$('[data-table]').forEach(b=>b.classList.toggle('active',b.dataset.table===tab));account();ctx.toast('Paper position saved · no real order');});$$('[data-table]').forEach(b=>b.onclick=()=>{tab=b.dataset.table;$$('[data-table]').forEach(e=>e.classList.toggle('active',e===b));account();});$$('[data-interval]').forEach(b=>b.onclick=()=>{interval=b.dataset.interval;cursor=-1;$$('[data-interval]').forEach(e=>e.classList.toggle('active',e===b));drawChart();loadChart();});$('#chart-type').onclick=()=>{line=!line;drawChart();};$('#chart-full').onclick=()=>{const el=$('#t-chart-wrap');if(document.fullscreenElement)document.exitFullscreen?.();else el.requestFullscreen?.();};$('#chart-save').onclick=()=>{const a=document.createElement('a');a.href=$('#app-chart').toDataURL('image/png');a.download=`${symbol}-${interval}-reference.png`;a.click();};$('#app-chart').onpointermove=e=>{const r=e.currentTarget.getBoundingClientRect();cursor=Math.max(0,Math.min(series().length-1,Math.floor((e.clientX-r.left-10)/(r.width-72)*series().length)));drawChart();};$('#app-chart').onpointerleave=()=>{cursor=-1;drawChart();};updateMath();account();drawChart();loadChart();}

 function pools(){return `<div class="t-page">${hero('EXPLORE <span>EVERY POOL</span>','Pools','Public Solana pools, organized by liquidity and activity. Open a pool to inspect its market and continue to its venue.','pools','<a class="button white" href="/app/pools/new">Create pool</a>')}<div class="t-filters"><input class="search-input" id="pool-search" placeholder="Search by symbol or address" aria-label="Search pools"><div class="segments">${['all','meteora','raydium','orca','saved'].map(v=>`<button data-pool-type="${v}" class="${poolType===v?'active':''}">${v==='all'?'All':v==='saved'?'Saved':v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div><span class="t-source"><i class="status-dot"></i>${esc(ctx.sourceLabel().split(' · ')[0])}</span><button id="refresh-pools" class="t-refresh" aria-label="Refresh pools">↻</button></div><div class="t-scroll panel"><table class="t-table"><thead><tr><th>POOL</th><th>TYPE</th><th>PRICE</th><th><button data-pool-sort="liquidity">LIQUIDITY (USD) ↓</button></th><th><button data-pool-sort="volume">VOLUME 24H ↓</button></th><th>24H CHANGE</th><th>BUYS / SELLS</th><th></th></tr></thead><tbody id="pool-rows"></tbody></table></div><p class="t-page-note">A fetched Solana pool sample from DexScreener. Pools and tokens are created independently; a listing is not an endorsement. Fees and executable quotes must be checked at the venue.</p></div>`;}
 function updatePools(){const el=$('#pool-rows');if(!el)return;const query=$('#pool-search').value.toLowerCase();const list=(ctx.data()?.pools||[]).filter(p=>(poolType==='all'||poolType==='saved'&&watchlist.includes(p.id)||p.dex===poolType)&&`${p.base.symbol} ${p.quote.symbol} ${p.id}`.toLowerCase().includes(query)).sort((a,b)=>(b[poolSort]||0)-(a[poolSort]||0));el.innerHTML=list.length?list.map(p=>`<tr><td><a class="t-pair" href="/app/pools/${encodeURIComponent(p.id)}">${coin(p.base.symbol)}<strong>${esc(p.base.symbol)} / ${esc(p.quote.symbol)}</strong></a></td><td><span class="t-type">${esc(p.dex)}</span></td><td>${money(p.price)}</td><td>${compact(p.liquidity)}</td><td>${compact(p.volume)}</td><td class="${p.change<0?'bad':'good'}">${pct(p.change)}</td><td>${num(p.buys)} / ${num(p.sells)}</td><td><button data-watch="${esc(p.id)}" aria-label="${watchlist.includes(p.id)?'Unsave':'Save'} pool">${watchlist.includes(p.id)?'★':'☆'}</button></td></tr>`).join(''):'<tr><td colspan="8" class="empty">No matching pools. Try another filter or refresh.</td></tr>';$$('[data-watch]').forEach(b=>b.onclick=()=>{watchlist=watchlist.includes(b.dataset.watch)?watchlist.filter(v=>v!==b.dataset.watch):[...watchlist,b.dataset.watch];ctx.write('watchlist',watchlist);updatePools();});}
 function bindPools(){$('#pool-search').oninput=updatePools;$$('[data-pool-type]').forEach(b=>b.onclick=()=>{poolType=b.dataset.poolType;$$('[data-pool-type]').forEach(e=>e.classList.toggle('active',e===b));updatePools();});$$('[data-pool-sort]').forEach(b=>b.onclick=()=>{poolSort=b.dataset.poolSort;updatePools();});$('#refresh-pools').onclick=async()=>{ctx.toast('Refreshing public pools…');await ctx.refreshData();updatePools();};updatePools();}
 function poolDetail(id){const p=ctx.data()?.pools?.find(p=>p.id===id);if(!p)return `<div class="t-page">${hero('EXPLORE <span>POOL</span>','Pool unavailable','The pair is outside the current fetched sample. Return to pools to load the latest list.','pools','<a class="button white" href="/app/pools">All pools →</a>')}</div>`;return `<div class="t-page"><a class="t-back" href="/app/pools">‹ Pools</a>${hero('SOLANA <span>'+esc(p.dex.toUpperCase())+'</span>',esc(p.base.symbol)+' / '+esc(p.quote.symbol),'Public pool details. Review liquidity and activity before continuing to the execution venue.','pools')}<div class="t-facts t-detail-facts panel"><div><small>PRICE</small><strong>${money(p.price)}</strong></div><div><small>LIQUIDITY</small><strong>${compact(p.liquidity)}</strong></div><div><small>VOLUME 24H</small><strong>${compact(p.volume)}</strong></div><div><small>24H CHANGE</small><strong>${pct(p.change)}</strong></div><div><small>BUYS / SELLS</small><strong>${num(p.buys)} / ${num(p.sells)}</strong></div><div><small>VENUE</small><strong>${esc(p.dex)}</strong></div></div><div class="t-two"><section class="panel t-pad"><h2>Pool market</h2><p class="caption">${esc(p.id)}</p><a class="button white" href="${safeURL(p.url)}" target="_blank" rel="noopener">Open pool on DexScreener ↗</a><p class="caption">Quotes and liquidity actions are handled by the external venue.</p></section><section class="panel t-pad"><h2>Your position</h2><p class="caption">No LP position is held or managed by this interface.</p>${walletButton()}</section></div></div>`;}
 function createPool(){return `<div class="t-page"><a class="t-back" href="/app/pools">‹ Pools</a>${hero('POOLS <span>/ NEW POOL</span>','Create pool','Prepare a pair, then review the actual pool configuration and transaction on a Solana liquidity venue.','pools')}<div class="t-two"><form class="panel t-pad" id="pool-plan"><h2>Pair and liquidity</h2><div class="field-row"><label class="field-label">Base asset<select class="field" id="pool-base"><option>SOL</option><option>USDC</option></select></label><label class="field-label">Quote asset<select class="field" id="pool-quote"><option>USDC</option><option>SOL</option></select></label></div><div class="field-row"><label class="field-label">Base amount<input class="field" id="pool-base-amount" type="number" min="0" step="any" placeholder="0"></label><label class="field-label">Quote amount<input class="field" id="pool-quote-amount" type="number" min="0" step="any" placeholder="0"></label></div><p class="caption">This prepares a local plan. Pool fees, token admission and signing are determined by the venue.</p><button class="button white" type="submit">Save pool plan</button></form><section class="panel t-pad"><p class="t-kicker mono">REVIEW</p><h2 id="pool-plan-pair">SOL / USDC</h2><dl class="definition"><div><dt>Starting ratio</dt><dd id="pool-plan-ratio">—</dd></div><div><dt>Network</dt><dd>Solana</dd></div><div><dt>Execution</dt><dd>On selected venue</dd></div></dl><a class="button white t-full" href="https://app.meteora.ag/" target="_blank" rel="noopener">Continue on Meteora ↗</a></section></div></div>`;}

 function swap(){return `<div class="t-page">${hero('TRADE <span>BEST ROUTE</span>','Swap','A clear view of your Solana swap. Estimate the amount here, then review the executable route, minimum output and fees on Jupiter.','swap')}<div class="t-two t-swap-layout"><section class="panel t-swap"><div class="t-between"><span>Paying from your connected wallet.</span>${funding()}</div><div class="amount-box"><label for="swap-amount">You pay</label><div class="amount-value"><input id="swap-amount" type="number" min="0" max="1000000000" step="any" placeholder="0" value="${swapAmount||''}"><button class="t-token-select" id="swap-token-from">${coin(swapReverse?'USDC':'SOL')}${swapReverse?'USDC':'SOL'}⌄</button></div></div><button class="swap-arrow" id="swap-reverse" aria-label="Reverse swap direction">⇅</button><div class="amount-box"><label>You receive</label><div class="amount-value"><strong id="swap-output">0</strong><button class="t-token-select" id="swap-token-to">${coin(swapReverse?'SOL':'USDC')}${swapReverse?'SOL':'USDC'}⌄</button></div></div><div class="t-slippage"><span>Slippage tolerance</span><div class="segments">${[.1,.5,1].map(v=>`<button data-swap-slip="${v}" class="${swapSlip===v?'active':''}">${v}%</button>`).join('')}</div></div><div class="t-order-action"><p>Get an executable quote and review the transaction on Jupiter. Nothing is signed here.</p><a id="jupiter-swap" class="button white t-full" href="https://jup.ag/swap/${swapReverse?'USDC-SOL':'SOL-USDC'}" target="_blank" rel="noopener">Review swap on Jupiter ↗</a></div></section><section class="panel t-quote"><p class="t-kicker mono">QUOTE</p><div id="swap-quote-details"><p>Enter an amount to see the reference rate, estimated output and route.</p></div></section></div></div>`;}
 function updateSwap(){const price=ctx.market('SOL')?.price,valid=swapAmount>0&&swapAmount<=1e9&&price>0,out=valid?(swapReverse?swapAmount/price:swapAmount*price):0;$('#swap-output').textContent=num(out);$('#swap-quote-details').innerHTML=valid?`<dl class="definition"><div><dt>Reference price</dt><dd>${money(price)} / SOL</dd></div><div><dt>Estimated output</dt><dd>${num(out)} ${swapReverse?'SOL':'USDC'}</dd></div><div><dt>Slippage setting</dt><dd>${swapSlip}%</dd></div><div><dt>Route / fees / price impact</dt><dd>Quoted on Jupiter</dd></div></dl><p class="caption">Indicative conversion, assuming USDC = $1. Not an executable quote. Final minimum output and route are set by Jupiter.</p>`:'<p>Enter an amount to see the reference rate, estimated output and route.</p>';}
 function bindSwap(){$('#swap-amount').oninput=e=>{swapAmount=+e.target.value;updateSwap();};const reverse=()=>{swapReverse=!swapReverse;render('/app/swap');};$('#swap-reverse').onclick=reverse;$('#swap-token-from').onclick=reverse;$('#swap-token-to').onclick=reverse;$$('[data-swap-slip]').forEach(b=>b.onclick=()=>{swapSlip=+b.dataset.swapSlip;$$('[data-swap-slip]').forEach(e=>e.classList.toggle('active',e===b));updateSwap();});updateSwap();}

 async function loadLaunches(){if(launchLoading)return;launchLoading=true;try{const r=await fetch('/api/launches',{signal:AbortSignal.timeout(18000)});if(!r.ok)throw Error();const d=await r.json();if(Array.isArray(d.tokens))launchData=d;}catch{if(!launchData)launchData={tokens:[],error:'Public launch data temporarily unavailable'};}finally{launchLoading=false;if($('#launch-cards'))updateLaunches();}}
 function launches(){return `<div class="t-page">${hero('LAUNCH <span>BONDING CURVES</span>','Launches','Explore pump.fun-origin tokens on Solana, inspect their public market data, or prepare a token of your own. Saved drafts stay in this browser.','curve','<a class="button white" href="/app/launch/new">Create a token →</a><a class="t-text-button" href="/docs#status">Read the guide</a>')}<div class="t-filters"><input class="search-input" id="launch-search" placeholder="Search by name, symbol or address" aria-label="Search launches"><div class="segments">${['All','Trading','Market pool','Drafts'].map(v=>`<button data-launch-filter="${v}" class="${v===launchFilter?'active':''}">${v}</button>`).join('')}</div><label class="t-sort">Sort <select id="launch-sort" class="field"><option value="newest">Newest</option><option value="volume">Volume 24h</option><option value="liquidity">Liquidity</option></select></label><span class="t-source" id="launch-source">Loading public markets…</span></div><div class="t-launch-grid" id="launch-cards"></div><p class="t-page-note">External Solana tokens, not launches created by Solveil. Pump.fun-origin is identified by the mint suffix; verify each token and its original launch transaction. Market-pool state comes from its quoted venue; no bonding-curve progress is inferred.</p></div>`;}
 function updateLaunches(){const query=$('#launch-search').value.toLowerCase(),local=ctx.read('drafts').filter(d=>validateDraft(d).value),publicTokens=launchData?.tokens||[];let list=launchFilter==='Drafts'?local.map(d=>({...d,mint:d.id,state:'Draft',createdAt:d.updatedAt})):publicTokens.filter(d=>launchFilter==='All'||d.state===launchFilter);list=list.filter(d=>`${d.name} ${d.symbol} ${d.mint}`.toLowerCase().includes(query));list.sort((a,b)=>launchSort==='newest'?(new Date(b.createdAt||0)-new Date(a.createdAt||0)):(b[launchSort]||0)-(a[launchSort]||0));$('#launch-source').textContent=launchData?.asOf?`${launchData.snapshot?'Snapshot':'Updated'} ${new Date(launchData.asOf).toLocaleTimeString('en-US')}`:launchData?.error||'Loading public markets…';$('#launch-cards').innerHTML=list.length?list.map(d=>`<a class="panel t-launch-card" href="${d.state==='Draft'?'/app/launch/new?draft='+encodeURIComponent(d.id):'/app/launch/'+encodeURIComponent(d.mint)}"><div class="t-launch-identity">${d.image&&/^https:|^data:image\//.test(d.image)?`<img src="${esc(d.image)}" alt="" loading="lazy">`:`<span>${esc(d.symbol?.[0]||'?')}</span>`}<div><h3>${esc(d.name)}</h3><small>${esc(d.symbol)} · ${d.createdAt?new Date(d.createdAt).toLocaleDateString('en-US'):'Solana'}</small></div><b class="pill">${esc(d.state)}</b></div><div class="t-launch-cap"><small>MARKET CAP</small><strong>${d.state==='Draft'?'Not launched':compact(d.marketCap)}</strong></div><div class="t-between"><span>${d.state==='Draft'?'Local draft':'Pool liquidity'}</span><b>${d.state==='Draft'?'Not on-chain':compact(d.liquidity)}</b></div><div class="t-liquidity-line"><i style="width:${d.state==='Draft'?0:100}%"></i></div><div class="t-launch-bottom"><div><small>PRICE</small><strong>${money(d.price)}</strong></div><div><small>VOL 24H</small><strong>${compact(d.volume)}</strong></div><div><small>TRADES 24H</small><strong>${d.state==='Draft'?'—':num((d.buys||0)+(d.sells||0))}</strong></div></div></a>`).join(''):`<div class="panel empty">${launchLoading?'Loading public launches…':launchFilter==='Drafts'?'No saved drafts yet. Create your first token plan.':'No tokens match this view. Try another filter.'}</div>`;}
 function bindLaunchList(){$('#launch-search').oninput=updateLaunches;$('#launch-sort').value=launchSort;$('#launch-sort').onchange=e=>{launchSort=e.target.value;updateLaunches();};$$('[data-launch-filter]').forEach(b=>b.onclick=()=>{launchFilter=b.dataset.launchFilter;$$('[data-launch-filter]').forEach(e=>e.classList.toggle('active',e===b));updateLaunches();});updateLaunches();loadLaunches();}
 function launchDetail(mint){const d=launchData?.tokens?.find(d=>d.mint===mint);if(!d)return `<div class="t-page">${hero('LAUNCH <span>PUBLIC MARKET</span>','Token market','This token is outside the current sample. View its mint directly or return to the latest launches.','curve',`<a class="button white" href="https://pump.fun/coin/${encodeURIComponent(mint)}" target="_blank" rel="noopener">View on pump.fun ↗</a><a href="/app/launch">All launches</a>`)}</div>`;return `<div class="t-page"><a class="t-back" href="/app/launch">‹ Launches</a>${hero('LAUNCH <span>'+esc(d.state.toUpperCase())+'</span>',esc(d.name),esc(d.description||d.symbol+' · Solana public market'), 'curve')}<div class="t-two"><section class="panel t-pad"><div class="t-launch-identity">${d.image?`<img src="${safeURL(d.image)}" alt="">`:coin(d.symbol)}<h2>${esc(d.symbol)}</h2><span class="pill">${esc(d.dex)}</span></div><div class="t-facts"><div><small>PRICE</small><strong>${money(d.price)}</strong></div><div><small>MARKET CAP</small><strong>${compact(d.marketCap)}</strong></div><div><small>LIQUIDITY</small><strong>${compact(d.liquidity)}</strong></div><div><small>VOLUME 24H</small><strong>${compact(d.volume)}</strong></div></div></section><section class="panel t-pad"><h2>Trade this token</h2><p class="caption t-address">${esc(d.mint)}</p><a class="button white t-full" href="https://pump.fun/coin/${encodeURIComponent(d.mint)}" target="_blank" rel="noopener">Open on pump.fun ↗</a><a class="button t-full" href="${safeURL(d.url)}" target="_blank" rel="noopener">Inspect the public market ↗</a><p class="caption">External token. Check its actual mint, fees and venue before signing.</p></section></div></div>`;}

 function newLaunch(){let d=ctx.read('working-draft',{});const selected=new URLSearchParams(location.search).get('draft');if(selected){const saved=ctx.read('drafts').find(v=>v.id===selected);if(saved){d=saved;draftId=saved.id;}}image=d.image||'';quote=d.quote||'SOL';tier=d.tier||'standard';return `<div class="t-page"><a class="t-back" href="/app/launch">‹ Launches</a>${hero('LAUNCH <span>/ NEW TOKEN</span>','Create a token','Choose the pair and prepare your token details. Preview the plan, save a portable draft, then review the actual launch terms on pump.fun.','curve')}<div class="t-two t-create-layout"><form id="launch-form"><section class="panel t-form-section"><h3><span>01</span> Pair and size</h3><p>Planning preferences. The launch venue determines the final economics.</p><label class="field-label">Pair</label><div class="t-choice-grid">${['SOL','USDC'].map(v=>`<button type="button" data-quote="${v}" class="t-choice ${quote===v?'active':''}"><strong>${v}</strong><small>${v==='SOL'?'Solana native quote asset.':'Dollar-denominated planning reference.'}</small></button>`).join('')}</div><label class="field-label" style="margin-top:18px">Size</label><div class="t-choice-grid three">${['quick','standard','big'].map(v=>`<button type="button" data-tier="${v}" class="t-choice ${tier===v?'active':''}"><strong>${v[0].toUpperCase()+v.slice(1)}</strong><small>${v==='quick'?'Small launch plan':v==='standard'?'Standard launch plan':'Larger launch plan'}</small></button>`).join('')}</div><p class="caption">These are draft labels, not deployed bonding-curve parameters.</p></section><section class="panel t-form-section"><h3><span>02</span> Token details</h3><p>Review the final name and ticker at the launch venue before signing.</p><div class="field-row"><label class="field-label">Name<input class="field" id="token-name" maxlength="32" required value="${esc(d.name||'')}" placeholder="Token name"></label><label class="field-label">Symbol<input class="field" id="token-symbol" maxlength="10" required value="${esc(d.symbol||'')}" placeholder="TICKER"></label></div><label class="field-label">Description <small>optional · max 500</small><textarea class="field" id="token-description" maxlength="500">${esc(d.description||'')}</textarea></label></section><section class="panel t-form-section"><h3><span>03</span> Image and links</h3><p>Optional</p><label class="upload" for="token-image"><img id="upload-preview" src="${image?esc(image):'/assets/mark-blue.svg'}" alt="Token artwork preview"><span><strong>Upload an image</strong><small>PNG, JPEG or WebP · under 1.3 MB. Drop it here or click to choose.</small></span><input id="token-image" type="file" accept="image/png,image/jpeg,image/webp" hidden></label><label class="field-label">Website<input class="field" type="url" id="token-website" value="${esc(d.website||'')}" placeholder="https://"></label><label class="field-label">X<input class="field" type="url" id="token-social" value="${esc(d.social||'')}" placeholder="https://x.com/"></label></section><section class="panel t-form-section"><h3><span>04</span> Launch handoff</h3><p>Export the details or copy them into the chosen venue. The venue controls its fee recipients, supply, initial buy and transaction.</p><div class="draft-actions"><button class="button white" type="submit">Save draft</button><button class="button" type="button" id="export-draft">Export JSON ↗</button><button class="button" type="button" id="copy-draft">Copy details</button><label class="button">Import draft<input type="file" id="import-draft" accept=".json,application/json" hidden></label></div></section></form><aside class="panel t-review"><p class="t-kicker mono">REVIEW</p><h2 id="preview-name">Your token</h2><p id="preview-symbol" class="caption">$TICKER · Solana</p><div id="launch-preview-art" class="t-draft-image"></div><p id="preview-description" class="caption"></p><dl class="definition t-review-list"><div><dt>Template</dt><dd id="review-tier">Standard plan</dd></div><div><dt>Quote preference</dt><dd id="review-quote">SOL</dd></div><div><dt>Network</dt><dd>Solana</dd></div><div><dt>Total supply</dt><dd>Set by the launch venue</dd></div><div><dt>Curve fee</dt><dd>Review at launch</dd></div><div><dt>Graduation threshold</dt><dd>Review at launch</dd></div><div><dt>Pool after graduation</dt><dd>Venue configured</dd></div><div><dt>Creator fee recipient</dt><dd>Set at the venue</dd></div><div><dt>Metadata</dt><dd id="review-metadata">None</dd></div><div><dt>On-chain status</dt><dd>Not deployed</dd></div></dl><p class="caption">A draft is not a created token. Actual economics and wallet signing are handled on pump.fun.</p><a class="button white t-full" href="https://pump.fun/create" target="_blank" rel="noopener">Review on pump.fun ↗</a><div id="draft-list" class="t-local-drafts"></div></aside></div></div>`;}
 function formDraft(){return {name:$('#token-name').value,symbol:$('#token-symbol').value,description:$('#token-description').value,website:$('#token-website').value,social:$('#token-social').value,image,quote,tier};}
 function previewDraft(){const d=formDraft();$('#preview-name').textContent=d.name||'Your token';$('#preview-symbol').textContent='$'+(d.symbol.toUpperCase()||'TICKER')+' · Solana';$('#preview-description').textContent=d.description;$('#launch-preview-art').innerHTML=image?`<img src="${esc(image)}" alt="Draft artwork">`:'';$('#upload-preview').src=image||'/assets/mark-blue.svg';$('#review-tier').textContent=tier[0].toUpperCase()+tier.slice(1)+' plan';$('#review-quote').textContent=quote;$('#review-metadata').textContent=d.image||d.description?'Local draft':'None';ctx.write('working-draft',d);}
 function validated(){const result=validateDraft(formDraft());if(result.error){ctx.toast(result.error);return null;}return {...result.value,quote,tier,network:'solana:mainnet',status:'local-draft'};}
 function bindNewLaunch(){const form=$('#launch-form');form.oninput=previewDraft;form.onsubmit=e=>{e.preventDefault();const d=validated();if(!d)return;const saved={...d,id:draftId||crypto.randomUUID(),updatedAt:new Date().toISOString()};draftId=saved.id;ctx.write('drafts',[...ctx.read('drafts').filter(v=>v.id!==saved.id).slice(-9),saved]);ctx.toast('Draft saved locally · no token created');};$$('[data-quote]').forEach(b=>b.onclick=()=>{quote=b.dataset.quote;$$('[data-quote]').forEach(e=>e.classList.toggle('active',e===b));previewDraft();});$$('[data-tier]').forEach(b=>b.onclick=()=>{tier=b.dataset.tier;$$('[data-tier]').forEach(e=>e.classList.toggle('active',e===b));previewDraft();});const imageFile=file=>{if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>1300000){ctx.toast('Choose PNG, JPEG or WebP under 1.3 MB.');return;}const reader=new FileReader();reader.onload=()=>{image=String(reader.result);previewDraft();};reader.readAsDataURL(file);};$('#token-image').onchange=e=>imageFile(e.target.files[0]);$('.upload').ondragover=e=>e.preventDefault();$('.upload').ondrop=e=>{e.preventDefault();imageFile(e.dataTransfer.files[0]);};$('#export-draft').onclick=()=>{const d=validated();if(d)ctx.download(d.symbol.toLowerCase()+'-draft.json',d);};$('#copy-draft').onclick=()=>{const d=validated();if(d)ctx.copy(`${d.name} ($${d.symbol})\n\n${d.description}\n\n${d.website}\n${d.social}`);};$('#import-draft').onchange=async e=>{const file=e.target.files[0];if(!file||file.size>2000000){ctx.toast('Use a draft JSON under 2 MB.');return;}try{const d=JSON.parse(await file.text()),valid=validateDraft(d);if(!valid.value)throw Error(valid.error);ctx.write('working-draft',{...valid.value,quote:['SOL','USDC'].includes(d.quote)?d.quote:'SOL',tier:['quick','standard','big'].includes(d.tier)?d.tier:'standard'});draftId=null;render('/app/launch/new');}catch(e){ctx.toast(e.message||'Invalid draft file');}};previewDraft();}

 function vault(){const wallet=ctx.wallet();return `<div class="t-page">${hero('PRIVATE <span>SHIELDED</span>','Vault','Your wallet stays under your control. This Solana version includes the vault layout; shielded deposits and transfers are not deployed.','vault')}<div class="t-vault-notice">♧ &nbsp; Solana transfers are public. This preview never creates a recovery phrase or accepts funds into a private vault.</div><div class="t-two"><section class="panel t-pad"><h2>Public wallet account</h2><p>Connect a Solana wallet to read its public address and confirmed native balance. No signature or transfer is requested.</p>${wallet.address?`<p class="t-address">${esc(wallet.address)}</p><strong class="t-wallet-number">${wallet.balance===null?'Unavailable':num(wallet.balance)+' SOL'}</strong><div class="draft-actions"><button class="button" id="refresh-balance">Refresh balance</button><button class="button" id="disconnect-wallet">Disconnect</button></div>`:walletButton()}</section><section class="panel t-pad"><h2>Shielded account</h2><p>Separate Solana privacy infrastructure is required to support deposits, private transfers, recovery and proof verification.</p><button class="button t-full" disabled>Solana module not deployed</button><a class="t-text-button" href="/docs#status">Read the current product status →</a></section></div><details class="t-vault-faq"><summary>How this works, and what it does not hide<i></i></summary><p>Your connected wallet is a public Solana address. The site reads its balance through a public RPC. It does not hide ownership or transactions, and it never requests your recovery phrase.</p></details></div>`;}

 function render(path){renderedPath=path;header();const parts=path.split('/').filter(Boolean),page=parts[1]||'perps',id=parts[2];const root=$('#app-view');root.innerHTML=page==='pools'?(id==='new'?createPool():id?poolDetail(id):pools()):page==='swap'?swap():page==='launch'?(id==='new'?newLaunch():id?launchDetail(id):launches()):page==='vault'||page==='wallet'?vault():perps();if(page==='perps'||!['pools','swap','launch','vault','wallet'].includes(page))bindPerps();if(page==='swap')bindSwap();if(page==='pools'&&!id)bindPools();if(page==='launch'&&!id)bindLaunchList();if(page==='launch'&&id==='new')bindNewLaunch();if(page==='vault'||page==='wallet'){if($('#refresh-balance'))$('#refresh-balance').onclick=ctx.readBalance;if($('#disconnect-wallet'))$('#disconnect-wallet').onclick=ctx.disconnect;}
 if(page==='pools'&&id==='new'){const update=()=>{const base=$('#pool-base').value,quote=$('#pool-quote').value,a=+$('#pool-base-amount').value,b=+$('#pool-quote-amount').value;$('#pool-plan-pair').textContent=base+' / '+quote;$('#pool-plan-ratio').textContent=a>0&&b>0&&base!==quote?num(b/a)+' '+quote+' / '+base:'—';};$('#pool-plan').oninput=update;$('#pool-plan').onsubmit=e=>{e.preventDefault();const base=$('#pool-base').value,quote=$('#pool-quote').value,a=+$('#pool-base-amount').value,b=+$('#pool-quote-amount').value;if(base===quote||!Number.isFinite(a)||!Number.isFinite(b)||a<=0||b<=0){ctx.toast('Use different assets and positive amounts.');return;}ctx.download('solana-pool-plan.json',{network:'solana:mainnet',base,quote,baseAmount:a,quoteAmount:b,status:'local-plan'});};}
 bindFunding();startArt();}
 function refresh(){if($('#app-chart')){for(const [id,value] of Object.entries({'t-current':num(m()?.price),'t-high':num(m()?.high),'t-low':num(m()?.low),'t-reference':num(m()?.price),'t-volume':compact(m()?.volume)})){const e=$('#'+id);if(e)e.textContent=value;}$('#t-change').textContent=pct(m()?.change);$$('[data-price-symbol]').forEach(e=>e.textContent=num(ctx.market(e.dataset.priceSymbol)?.price));$$('[data-change-symbol]').forEach(e=>{const change=ctx.market(e.dataset.changeSymbol)?.change;e.textContent=pct(change);e.className=change<0?'bad':'good';});$$('[data-symbol]').forEach(e=>{const trend=e.querySelector('.t-market-trend');if(trend&&!trend.querySelector('svg'))trend.insertAdjacentHTML('afterbegin',spark(ctx.market(e.dataset.symbol)?.candles));});const w=ctx.wallet();$('#t-wallet-balance').textContent=w.address?(w.balance===null?'Unavailable':num(w.balance)):'Not connected';drawChart();updateMath();account();}if($('#pool-rows'))updatePools();if($('#swap-output'))updateSwap();if($('#launch-cards'))updateLaunches();}
 addEventListener('resize',drawChart);addEventListener('fullscreenchange',()=>requestAnimationFrame(drawChart));
 return {render,refresh};
}
